// ===== Variables =====
$primary: #FF8C69;
$primary-light: #FFB347;
$primary-dark: #E87350;
$bg-warm: #FFF9F0;
$bg-light: #FFF3E4;
$bg-card: #FFFFFF;
$text-primary: #5D4E37;
$text-secondary: #9E8E7E;
$text-muted: #B5A898;
$success: #7BC47F;
$error: #F07167;
$accent-mint: #A8D8A8;
$accent-pink: #FFD1DC;
$border: #EDE5DA;
$shadow-sm: 0 2px 8px rgba(93, 78, 55, 0.06);
$shadow-md: 0 4px 16px rgba(93, 78, 55, 0.1);
$shadow-lg: 0 8px 32px rgba(93, 78, 55, 0.14);
