// ===== Reset & Base =====
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --primary: #{$primary};
  --primary-light: #{$primary-light};
  --bg-warm: #{$bg-warm};
  --bg-light: #{$bg-light};
  --bg-card: #{$bg-card};
  --text-primary: #{$text-primary};
  --text-secondary: #{$text-secondary};
  --shadow-sm: #{$shadow-sm};
  --shadow-md: #{$shadow-md};
  --shadow-lg: #{$shadow-lg};
  --radius-md: #{$radius-md};
}

body {
  font-family: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: $bg-warm;
  color: $text-primary;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

#app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: $primary;
  text-decoration: none;
  transition: $transition;

  &:hover {
    color: $primary-dark;
  }
}

button {
  cursor: pointer;
  border: none;
  outline: none;
  font-family: inherit;
  transition: $transition;
}

input, textarea, select {
  font-family: inherit;
  outline: none;
  transition: $transition;
}

img {
  max-width: 100%;
  display: block;
}

// ===== Layout =====
.app-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.main-content {
  flex: 1;
  padding: 24px;
  max-width: 1400px;
  width: 100%;
  margin: 0 auto;
}

.page-container {
  padding: 32px 24px;
  max-width: 1200px;
  margin: 0 auto;
}

// ===== Navbar =====
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  padding: 0 24px;
  background: $bg-card;
  box-shadow: $shadow-sm;
  position: sticky;
  top: 0;
  z-index: 100;

  .logo {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 1.25rem;
    font-weight: 600;
    color: $text-primary;

    .logo-icon {
      font-size: 1.5rem;
    }

    .heart {
      display: inline-block;
      animation: heartbeat 1.5s ease-in-out infinite;
    }
  }

  .nav-links {
    display: flex;
    align-items: center;
    gap: 4px;

    .nav-link {
      padding: 8px 16px;
      border-radius: $radius-sm;
      color: $text-secondary;
      font-size: 0.9rem;
      font-weight: 500;
      transition: $transition;

      &:hover {
        background: $bg-light;
        color: $text-primary;
      }

      &.router-link-active {
        color: $primary;
        background: rgba($primary, 0.08);
      }
    }
  }

  .nav-actions {
    display: flex;
    align-items: center;
    gap: 12px;

