import {
  Controller,
  Post,
  Get,
  Param,
  Delete,
  UploadedFile,
  UseInterceptors,
  Query,
} from '@nestjs/common'
import { FileInterceptor } from '@nestjs/platform-express'
import { MediaService } from '@media/media.service'
import { CurrentUser } from '@common/decorators/current-user.decorator'
import { QueryMediaDto } from '@media/dto/query-media.dto'

@Controller('media')
export class MediaController {
  constructor(private mediaService: MediaService) {}

  @Post('upload')
  @UseInterceptors(FileInterceptor('file'))
  upload(@UploadedFile() file: Express.Multer.File, @CurrentUser() user: any) {
    return this.mediaService.upload(file, user.sub)
  }

  @Get()
  findAll(@Query() dto: QueryMediaDto) {
    return this.mediaService.findAll(dto)
  }

  @Get('years')
  getYears() {
    return this.mediaService.getYears()
  }

  @Get('timeline')
  getTimeline() {
    return this.mediaService.getTimeline()
  }

  @Get(':id')
  findOne(@Param('id') id: string) {
    return this.mediaService.findOne(id)
  }

  @Delete(':id')
  remove(@Param('id') id: string) {
    return this.mediaService.remove(id)
  }
}

import { Entity, PrimaryGeneratedColumn, Column, CreateDateColumn, UpdateDateColumn } from 'typeorm'

@Entity('users')
export class User {
  @PrimaryGeneratedColumn('uuid')
  id: string

  @Column({ unique: true, length: 50 })
  username: string

  @Column({ unique: true, length: 100 })
  email: string

  @Column({ name: 'password_hash', length: 255 })
  passwordHash: string

  @Column({ name: 'nickname', length: 50, nullable: true })
  nickname: string

  @Column({ name: 'avatar_url', length: 255, nullable: true })
  avatarUrl: string

  @Column({ type: 'varchar', length: 20, default: 'MEMBER' })
  role: string

  @Column({ name: 'reset_token', length: 255, nullable: true })
  resetToken: string

  @Column({ name: 'reset_token_expires', type: 'datetime', nullable: true })
  resetTokenExpires: Date

  @CreateDateColumn({ name: 'created_at' })
  createdAt: Date

  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt: Date
}

