44	import { ref, onMounted, computed } from 'vue'
45	import { useMediaStore } from '@/stores/media'
46	import { useRouter } from 'vue-router'
47	
48	const mediaStore = useMediaStore()
49	const router = useRouter()
50	
51	const timeline = ref([])
52	const allMedia = ref([])
53	const expandedMonths = ref([]) // 已展开的月份，格式 "年-月"
54	const expandedYears = ref([]) // 已展开的年份
55	
56	// 每个月默认显示的张数，超出部分折叠，点击"查看全部"展开
57	const COLLAPSED_COUNT = 12
58	
59	onMounted(async () => {
60	  timeline.value = await mediaStore.fetchTimeline()
61	  await loadAllMedia()
62	  // 默认只展开最近一年（timeline 按年份倒序，第一个即最近）
63	  if (timeline.value.length) {
64	    expandedYears.value = [timeline.value[0].year]
65	  }
66	})
67	
68	// 分页加载全部媒体（不受单页 limit 上限影响，数据多的时候也能完整显示）
69	async function loadAllMedia() {
70	  try {
71	    const all = []
72	    let page = 1
73	    while (true) {
74	      const data = await mediaStore.fetchMedia({ page, limit: 100 })
75	      all.push(...data.items)
76	      if (page >= data.totalPages) break
77	      page++
78	    }
79	    allMedia.value = all
80	  } catch {
81	    allMedia.value = []
82	  }
83	}
84	
85	// 年份 → 月份 两级分组（月份倒序，最近的在前）
86	const timelineGroups = computed(() => {
87	  return timeline.value.map((item) => {
88	    const items = allMedia.value.filter((m) => m.year === item.year)
89	    const months = [...new Set(items.map((m) => m.month))].sort((a, b) => b - a)
90	    return {
91	      year: item.year,
92	      count: item.count,
93	      months: months.map((mo) => ({
94	        year: item.year,
95	        month: mo,
96	        items: items.filter((m) => m.month === mo),
97	      })),
98	    }
99	  })
100	})
101	
102	function monthKey(year, month) {
103	  return `${year}-${month}`
104	}
105	
106	function isYearExpanded(year) {
107	  return expandedYears.value.includes(year)
108	}
109	
110	function toggleYear(year) {
111	  const idx = expandedYears.value.indexOf(year)
112	  if (idx > -1) expandedYears.value.splice(idx, 1)
113	  else expandedYears.value.push(year)
114	}
115	
116	function isMonthExpanded(year, month) {
117	  return expandedMonths.value.includes(monthKey(year, month))
118	}
119	
120	function toggleMonth(year, month) {
121	  const key = monthKey(year, month)
122	  const idx = expandedMonths.value.indexOf(key)
123	  if (idx > -1) expandedMonths.value.splice(idx, 1)
124	  else expandedMonths.value.push(key)
125	}
