const { existsSync, mkdirSync, copyFileSync, statSync } = require('fs')
const { join } = require('path')
const { randomUUID } = require('crypto')
const { execFileSync } = require('child_process')
const Database = require('better-sqlite3')
const sharp = require('sharp')

async function main() {
  const ROOT = process.cwd()
  const db = new Database(join(ROOT, 'family_memoir.db'))
  const user = db.prepare('SELECT id FROM users LIMIT 1').get()

  const items = [
    { y: '2019', m: '11', d: '03', id: 10 },
    { y: '2021', m: '11', d: '03', id: 20 },
    { y: '2024', m: '11', d: '03', id: 30 },
  ]

  const insert = db.prepare(`INSERT INTO media
    (id, filename, original_path, thumbnail_path, media_type, file_size, mime_type,
     duration, width, height, taken_at, year, month, day, exif_data, uploaded_by, created_at, updated_at)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)

  for (const it of items) {
    const cache = join(ROOT, '.seed-cache', `otd_${it.id}.jpg`)
    if (!existsSync(cache)) execFileSync('curl', ['-sL', '--max-time', '60', '-o', cache, `https://picsum.photos/id/${it.id}/800/600`])
    const dir = join(ROOT, 'uploads', it.y, it.m, it.d)
    const tdir = join(ROOT, 'thumbnails', it.y, it.m, it.d)
    mkdirSync(dir, { recursive: true }); mkdirSync(tdir, { recursive: true })
    const name = `${Date.now()}_${randomUUID().slice(0, 8)}.jpg`
    copyFileSync(cache, join(dir, name))
    const meta = await sharp(join(dir, name)).metadata()
    await sharp(join(dir, name)).resize(400, null, { withoutEnlargement: true }).jpeg({ quality: 80 }).toFile(join(tdir, name.replace('.jpg', '_thumb.jpg')))
    const takenAt = `${it.y}-${it.m}-${it.d} 12:00:00`
    insert.run(randomUUID(), name, `/uploads/${it.y}/${it.m}/${it.d}/${name}`, `/thumbnails/${it.y}/${it.m}/${it.d}/${name.replace('.jpg', '_thumb.jpg')}`,
      'PHOTO', statSync(join(dir, name)).size, 'image/jpeg', 0, meta.width, meta.height,
      takenAt, +it.y, +it.m, +it.d, null, user.id, takenAt, takenAt)
    console.log(`added ${it.y}-${it.m}-${it.d} ${name}`)
  }
  db.close()
  console.log('done')
}
main().catch((e) => { console.error(e); process.exit(1) })
EOF
