cat > ./.tmp-dedup.js <<'EOF'
const { existsSync, unlinkSync } = require('fs')
const { join } = require('path')
const Database = require('better-sqlite3')
const db = new Database(join(process.cwd(), 'family_memoir.db'))
for (const [y, m, d] of [[2019, 11, 3], [2021, 11, 3]]) {
  const rows = db.prepare('SELECT id, original_path, thumbnail_path FROM media WHERE year=? AND month=? AND day=? ORDER BY created_at').all(y, m, d)
  const dupes = rows.slice(1)
  for (const r of dupes) {
    for (const p of [r.original_path, r.thumbnail_path]) {
      const fp = join(process.cwd(), p.replace(/^\/+/, '').replace(/\//g, '\\'))
      if (existsSync(fp)) unlinkSync(fp)
    }
    db.prepare('DELETE FROM media WHERE id=?').run(r.id)
  }
  console.log(`${y}-${m}-${d}: kept 1, removed ${dupes.length} duplicates`)
}
db.close()
EOF
